const CampaignsAdmin=(()=>{const $=id=>document.getElementById(id);const LABEL={DRAFT:"Draft",AWAITING_PAYMENT:"Awaiting payment",PAYMENT_REVIEW:"Payment under review",PAYMENT_REJECTED:"Payment rejected",AWAITING_APPROVAL:"Awaiting approval",CHANGES_REQUESTED:"Changes requested",SCHEDULED:"Scheduled",ACTIVE:"Active",PAUSED:"Paused",EXHAUSTED:"Paid days used",COMPLETED:"Completed",STOPPED:"Stopped"};const TONE={DRAFT:"muted",AWAITING_PAYMENT:"warn",PAYMENT_REVIEW:"warn",PAYMENT_REJECTED:"danger",AWAITING_APPROVAL:"warn",CHANGES_REQUESTED:"danger",SCHEDULED:"info",ACTIVE:"ok",PAUSED:"muted",EXHAUSTED:"muted",COMPLETED:"ok",STOPPED:"muted"};const FINAL=["COMPLETED","STOPPED"];const REFUNDABLE=["PAUSED","EXHAUSTED","COMPLETED","STOPPED"];let label="A$";let openId="";let current=null;const money=n=>{const v=Math.round(Number(n||0)*100)/100;return(v<0?"-":"")+label+Math.abs(v).toFixed(2)};const pill=s=>`<span class="cs-pill is-${TONE[s]||"muted"}">${escapeHtml(LABEL[s]||s)}</span>`;const when=iso=>iso?escapeHtml(new Date(iso).toLocaleString()):"—";const safeLink=url=>/^https:\/\//i.test(String(url||""))?url:"";async function load(){$("scad-status").textContent="Loading…";const res=await Api.post("adminListCampaigns",{token:Auth.getToken(),q:$("scad-q").value.trim(),filter:$("scad-filter").value});if(!res.ok){$("scad-status").textContent=res.error||"Could not load campaigns.";return}label=res.currencyLabel||label;const list=res.campaigns||[];$("scad-status").textContent=list.length?`${list.length} campaign(s).`:"Nothing here.";$("scad-list").innerHTML=list.length?`<table class="dash-table"><thead><tr><th scope="col">Campaign</th><th scope="col">Store</th><th scope="col">Days</th><th scope="col">Status</th><th scope="col"></th></tr></thead><tbody>${list.map(c=>`<tr>\n      <td data-label="Campaign"><div><strong>${escapeHtml(c.name||"Untitled")}</strong><span class="dash-table-sub">${escapeHtml(c.campaignId)}${c.references.length?" · "+escapeHtml(c.references.join(", ")):""}</span></div></td>\n      <td data-label="Store"><div>${escapeHtml(c.storeName||"")}</div></td>\n      <td data-label="Days"><div>${c.paidDays} paid · ${c.usedDays} used<span class="dash-table-sub">${c.days} planned · ${money(c.estimatedCost)}</span></div></td>\n      <td data-label="Status"><div>${pill(c.status)}${c.paymentsUnderReview.length?`<span class="dash-table-sub">${c.paymentsUnderReview.length} payment(s) to check</span>`:""}</div></td>\n      <td data-label=""><div><button type="button" class="btn btn-small" data-open="${escapeHtml(c.campaignId)}">Open</button></div></td></tr>`).join("")}</tbody></table>`:""}async function open(id){openId=id;$("scad-detail").hidden=false;$("scad-detail").innerHTML='<p class="helper-text">Loading…</p>';const res=await Api.post("adminGetCampaign",{token:Auth.getToken(),campaignId:id});if(!res.ok){$("scad-detail").innerHTML=`<p class="form-error">${escapeHtml(res.error||"Could not load the campaign.")}</p>`;return}current=res;render(res);$("scad-detail").scrollIntoView({behavior:"smooth",block:"start"})}function render(d){const c=d.campaign;const review=d.payments.filter(p=>p.status==="Under review");const unused=Math.max(0,c.paidDays-c.usedDays);const actions=[];if(c.status==="AWAITING_APPROVAL")actions.push('<button type="button" class="btn btn-small btn-light-purple" data-act="approve">Approve campaign</button>','<button type="button" class="btn btn-small" data-act="changes">Request changes</button>');if(c.status==="ACTIVE"||c.status==="SCHEDULED")actions.push('<button type="button" class="btn btn-small" data-act="pause">Pause</button>');if(FINAL.indexOf(c.status)===-1)actions.push('<button type="button" class="btn btn-small btn-danger" data-act="stop">Stop</button>');$("scad-detail").innerHTML=`\n      <div class="dash-panel-head"><h3>${escapeHtml(c.name||"Untitled")} ${pill(c.status)}</h3>\n        <button type="button" class="btn btn-small" data-act="close">Close</button></div>\n      <p class="helper-text">${escapeHtml(c.campaignId)} · ${escapeHtml(c.description||"")}</p>\n      ${c.statusNote?`<p class="helper-text"><strong>Note:</strong> ${escapeHtml(c.statusNote)}</p>`:""}\n      <p class="helper-text">Starts ${escapeHtml(c.startDate||"—")} · ${c.paidDays} paid days · ${c.usedDays} used · ${unused} unused · spent ${money(c.spent)} at ${money(c.dailyRate)}/day</p>\n      ${c.missing&&c.missing.length?`<p class="form-error">Missing: ${escapeHtml(c.missing.join(", "))}</p>`:""}\n      <div class="scad-actions">${actions.join(" ")}</div>\n      <h4>Email</h4>\n      <p class="helper-text"><strong>Subject:</strong> ${escapeHtml(d.preview?d.preview.subject:c.subject)}${c.previewText?` · <strong>Preview text:</strong> ${escapeHtml(c.previewText)}`:""}</p>\n      <iframe class="scad-preview" id="scad-preview" title="Email preview" sandbox=""></iframe>\n      <h4>Payments</h4>\n      ${d.payments.length?`<table class="dash-table"><thead><tr><th scope="col">Reference</th><th scope="col">Amount</th><th scope="col">Receipt check</th><th scope="col">Status</th></tr></thead><tbody>${d.payments.map(p=>`<tr>\n        <td data-label="Reference"><div><strong>${escapeHtml(p.reference)}</strong><span class="dash-table-sub">${escapeHtml(p.kind)} · ${p.days} days · submitted ${when(p.submittedAt)}</span></div></td>\n        <td data-label="Amount"><div>${money(p.amount)}</div></td>\n        <td data-label="Receipt check"><div>${safeLink(p.screenshotUrl)?`<a href="${escapeAttr(p.screenshotUrl)}" target="_blank" rel="noopener">View screenshot</a>`:"No screenshot"}\n          ${p.receiptNo?`<span class="dash-table-sub">Receipt no. ${escapeHtml(p.receiptNo)}</span>`:""}\n          ${p.checkNotes?`<span class="dash-table-sub">${escapeHtml(p.checkNotes)}</span>`:""}</div></td>\n        <td data-label="Status"><div>${escapeHtml(p.status)}${p.decidedBy?`<span class="dash-table-sub">${escapeHtml(p.decidedBy)} · ${when(p.decidedAt)}</span>`:""}${p.adminNote?`<span class="dash-table-sub">${escapeHtml(p.adminNote)}</span>`:""}\n          ${p.status==="Under review"?`<span class="scad-actions"><button type="button" class="btn btn-small btn-light-purple" data-pay="${escapeHtml(p.paymentId)}" data-verify="1">Verify</button>\n          <button type="button" class="btn btn-small" data-pay="${escapeHtml(p.paymentId)}" data-verify="0">Reject</button></span>`:""}</div></td></tr>`).join("")}</tbody></table>`:'<p class="dash-empty">No payments yet.</p>'}\n      ${review.length?'<p class="helper-text">Check the money arrived in the bank account with this exact reference before you press Verify. The receipt check above is only a pre-screen.</p>':""}\n      ${REFUNDABLE.indexOf(c.status)!==-1&&unused>0?`<form class="scad-refund" id="scad-refund" novalidate>\n        <h4>Record a refund</h4>\n        <p class="helper-text">Only after you have paid the seller back. Up to ${unused} unused day(s), ${money(unused*c.dailyRate)}.</p>\n        <div class="field"><label for="scad-refund-days">Days refunded</label><input id="scad-refund-days" type="number" min="1" max="${unused}" value="${unused}"></div>\n        <div class="field"><label for="scad-refund-reason">Reason</label><input id="scad-refund-reason" maxlength="300" placeholder="e.g. Seller asked on 20 Oct, paid back by ANZ transfer"></div>\n        <button type="submit" class="btn btn-small">Record refund</button></form>`:""}\n      <h4>Billing</h4>\n      ${d.ledger.length?`<table class="dash-table"><thead><tr><th scope="col">Entry</th><th scope="col">Days</th><th scope="col">Amount</th><th scope="col">By</th></tr></thead><tbody>${d.ledger.map(l=>`<tr>\n        <td data-label="Entry"><div>${escapeHtml(l.type)}<span class="dash-table-sub">${escapeHtml(l.day||l.reference||"")}${l.note?" · "+escapeHtml(l.note):""}</span></div></td>\n        <td data-label="Days"><div>${l.days}</div></td><td data-label="Amount"><div>${money(l.amount)}</div></td>\n        <td data-label="By"><div>${escapeHtml(l.by||"")}<span class="dash-table-sub">${when(l.at)}</span></div></td></tr>`).join("")}</tbody></table>`:'<p class="dash-empty">No billing entries yet.</p>'}\n      <h4>History</h4>\n      ${d.history.length?`<ol class="scad-history">${d.history.slice().reverse().map(h=>`<li>${when(h.at)} · <strong>${escapeHtml(h.action)}</strong> ${escapeHtml(LABEL[h.from]||h.from||"")} → ${escapeHtml(LABEL[h.to]||h.to||"")} · ${escapeHtml(h.by||"")}${h.note?" · "+escapeHtml(h.note):""}</li>`).join("")}</ol>`:'<p class="dash-empty">No history yet.</p>'}\n      <p id="scad-msg" class="helper-text" role="status" aria-live="polite"></p>`;$("scad-preview").srcdoc=d.preview?d.preview.html:""}async function run(action,body,done){const res=await Api.post(action,Object.assign({token:Auth.getToken()},body));if(!res.ok){const m=$("scad-msg");if(m)m.textContent=res.error||"That did not work.";else alert(res.error||"That did not work.");return}await open(openId);if($("scad-msg"))$("scad-msg").textContent=done;load()}function onDetailClick(e){const b=e.target.closest("button");if(!b||!current)return;const c=current.campaign;if(b.dataset.pay){const verify=b.dataset.verify==="1";const p=current.payments.find(x=>x.paymentId===b.dataset.pay);let reason="";if(verify){if(!confirm(`Verify ${p.reference} for ${money(p.amount)}? Only verify once you have seen this amount with this reference in the bank account.`))return}else{reason=prompt("Why is this payment not verified? The seller will see this.")||"";if(!reason.trim())return;if(!confirm(`Reject ${p.reference}?`))return}run("adminDecideCampaignPayment",{paymentId:p.paymentId,verify:verify,reason:reason,confirm:true},verify?"Payment verified.":"Payment rejected.");return}const act=b.dataset.act;if(act==="close"){$("scad-detail").hidden=true;current=null;openId="";return}if(act==="approve"){if(!confirm(`Approve "${c.name}"? Emails start from ${c.startDate} (Kiribati date), at the next hourly sweep.`))return;run("adminReviewCampaign",{campaignId:c.campaignId,approve:true},"Approved.")}else if(act==="changes"){const reason=prompt("What should the seller change? They will see this.")||"";if(!reason.trim())return;run("adminReviewCampaign",{campaignId:c.campaignId,approve:false,reason:reason},"Changes requested.")}else if(act==="pause"||act==="stop"){const reason=prompt(`Reason to ${act} this campaign (the seller will see it):`)||"";if(!reason.trim())return;if(act==="stop"&&!confirm(`Stop "${c.name}" for good? It cannot be restarted.`))return;run("adminCampaignAction",{campaignId:c.campaignId,op:act,reason:reason,confirm:true},act==="pause"?"Paused.":"Stopped.")}}function onRefund(e){if(e.target.id!=="scad-refund")return;e.preventDefault();const days=parseInt($("scad-refund-days").value,10);const reason=$("scad-refund-reason").value.trim();if(!(days>=1)){$("scad-msg").textContent="Enter the number of days refunded.";return}if(reason.length<5){$("scad-msg").textContent="Give a reason (at least 5 characters).";return}const c=current.campaign;if(!confirm(`Record a refund of ${days} day(s), ${money(days*c.dailyRate)}, for "${c.name}"? Only do this after the money has been paid back.`))return;run("adminRecordCampaignRefund",{campaignId:c.campaignId,days:days,reason:reason,confirm:true},"Refund recorded.")}function init(){if(!$("seller-campaigns"))return;$("scad-filter").addEventListener("change",load);$("scad-search").addEventListener("submit",e=>{e.preventDefault();load()});$("scad-list").addEventListener("click",e=>{const b=e.target.closest("[data-open]");if(b)open(b.dataset.open)});$("scad-detail").addEventListener("click",onDetailClick);$("scad-detail").addEventListener("submit",onRefund);load()}return{init:init}})();